      <Grid horizontal shimmer={loadingStyle === "sweep" ? false : gridShimmer} shimmerLength={gridShimmerLength} shimmerSpeed={gridShimmerSpeed} shimmerStroke={gridShimmerStroke} shimmerSync={gridShimmerSync} stroke={gridStroke}/>
      <Area curve={curveNatural} dataKey={LOADING_DATA_KEY} fadeEdges={false} fill="transparent" fillOpacity={0} loading loadingStroke={stroke} loadingStrokeOpacity={strokeOpacity} loadingStyle={loadingStyle} showHighlight={false} showLine stroke="transparent" strokeWidth={2}/>
