    </div>);
}
export { Area, type AreaProps } from "./area";
export default AreaChart;

import { type FadeEdges, fadeGradientStops, resolveFadeSides, viewportFadeGradientAttrs, } from "./fade-edges";
interface AreaGradientDefsProps {
    gradientId: string;
    strokeGradientId: string;
    edgeMaskId: string;
    edgeGradientId: string;
    fill: string;
    fillOpacity: number;
    gradientToOpacity: number;
    /** 0–1: where the bottom stop sits (1 = full-height gradient). */
    gradientSpan?: number;
    resolvedStroke: string;
    isPatternFill: boolean;
    fadeEdges: FadeEdges;
    innerWidth: number;
    innerHeight: number;
}
export function AreaGradientDefs({ gradientId, strokeGradientId, edgeMaskId, edgeGradientId, fill, fillOpacity, gradientToOpacity, gradientSpan = 1, resolvedStroke, isPatternFill, fadeEdges, innerWidth, innerHeight, }: AreaGradientDefsProps) {
    const sides = resolveFadeSides(fadeEdges);
    // Stroke gradient mirrors the area's edge fade so the line doesn't pop in
    // past the faded fill. Skip emitting it when neither edge fades — the line
    // can then paint a solid stroke instead of an unnecessary url(#...) ref.
    const strokeStops = sides.any ? fadeGradientStops(sides) : null;
    const showEdgeMask = sides.any && !isPatternFill;
    const edgeStops = showEdgeMask ? fadeGradientStops(sides) : null;
    const span = Math.min(1, Math.max(0.01, gradientSpan));
    const midOffset = `${span * 100}%`;
    return (<defs>
      {isPatternFill ? null : (<linearGradient id={gradientId} x1="0%" x2="0%" y1="0%" y2="100%">
          <stop offset="0%" style={{ stopColor: fill, stopOpacity: fillOpacity }}/>
          <stop offset={midOffset} style={{ stopColor: fill, stopOpacity: gradientToOpacity }}/>
          {span < 1 ? (<stop offset="100%" style={{ stopColor: fill, stopOpacity: gradientToOpacity }}/>) : null}
        </linearGradient>)}

      {strokeStops ? (<linearGradient id={strokeGradientId} {...viewportFadeGradientAttrs(innerWidth)}>
          {strokeStops.map((stop) => (<stop key={stop.offset} offset={stop.offset} style={{ stopColor: resolvedStroke, stopOpacity: stop.opacity }}/>))}
        </linearGradient>) : null}

      {edgeStops ? (<>
          <linearGradient id={edgeGradientId} {...viewportFadeGradientAttrs(innerWidth)}>
            {edgeStops.map((stop) => (<stop key={stop.offset} offset={stop.offset} style={{ stopColor: "white", stopOpacity: stop.opacity }}/>))}
          </linearGradient>
          <mask id={edgeMaskId}>
            <rect fill={`url(#${edgeGradientId})`} height={innerHeight} width={innerWidth} x="0" y="0"/>
          </mask>
        </>) : null}
    </defs>);
}

"use client";
import { curveMonotoneX } from "@visx/curve";
import { Area as AreaShape, AreaClosed, LinePath } from "@visx/shape";
import type { CurveFactory } from "d3-shape";
import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { useReducedMotion } from "motion/react";
import { isFiniteValue } from "./chart-data";
import { areaStackRange } from "./area-stack";
import { AreaGradientDefs } from "./area-gradient-defs";
import { chartCssVars, useChartStable, useYScale } from "./chart-context";
import type { ChartPhase, LoadingStyle } from "./chart-phase";
import { type FadeEdges, resolveFadeSides } from "./fade-edges";
import { type LineLoadingPulseMode, LineLoadingPulseStroke, resolveLineLoadingPulseMode, } from "./line-loading-pulse";
import { LINE_LOADING_LOOP_PAUSE_MS } from "./line-loading-timing";
import { LineLoadingSweep } from "./loading-sweep";
import { resolveDashTailBounds, usePathStrokeMetrics, } from "./path-stroke-utils";
import { SeriesDashTailOverlay } from "./series-dash-tail-overlay";
import { SeriesHighlightLayer } from "./series-highlight-layer";
import { SeriesHoverDim } from "./series-hover-dim";
import { SeriesMarkers } from "./series-markers";
import type { SeriesPointMarkerStyle } from "./series-point-marker";
export interface AreaProps {
    /** Key in data to use for y values */
    dataKey: string;
    /** Stack areas in child order within the same group and Y axis. Missing values leave a gap. */
    stackId?: string | number;
    /** Y-scale group id (Recharts `yAxisId`). Default: `"left"`. */
    yAxisId?: string | number;
    /** Fill color for the area gradient start. Default: var(--chart-1) */
    fill?: string;
    /** Fill opacity at the top of the area. Default: 0.4 */
    fillOpacity?: number;
    /** Stroke color for the line. Default: same as fill */
    stroke?: string;
    /** Stroke width. Default: 2 */
    strokeWidth?: number;
    /** Curve function. Default: curveMonotoneX */
    curve?: CurveFactory;
    /** Whether to animate the area. Default: true */
    animate?: boolean;
    /** Whether to show the stroke line. Default: true */
    showLine?: boolean;
    /** Whether to show highlight segment on hover. Default: true */
    showHighlight?: boolean;
    /** Gradient opacity at bottom (0 = fully transparent). Default: 0 */
    gradientToOpacity?: number;
    /**
     * Vertical extent of the fill gradient (0–1). `1` fades across the full
     * height; lower values compress the gradient toward the top.
     */
    gradientSpan?: number;
    /**
     * Fade the area fill (and stroke) toward transparent at the chart edges.
     * - `true` fades both edges, `false` disables the fade entirely.
     * - `"left"` / `"right"` fades only that side — useful when the opposite
     *   edge butts up against another element you don't want to fade into.
     * Default: false
     */
    fadeEdges?: FadeEdges;
    /** Render scatter-style circle markers at each data point. Default: false */
    showMarkers?: boolean;
    /** Marker styling (same options as Scatter). */
    markers?: SeriesPointMarkerStyle;
    /**
     * Data index from which the line stroke becomes dashed (inclusive).
     * Useful for projecting incomplete periods, e.g. dashed from yesterday through today.
     */
    dashFromIndex?: number;
    /** Dash pattern for the tail segment when `dashFromIndex` is set. Default: "6,4" */
    dashArray?: string;
    /** Pulse stroke color while chart is loading. Default: var(--fg-default) */
    loadingStroke?: string;
    /** Pulse stroke opacity while chart is loading. Default: 0.5 */
    loadingStrokeOpacity?: number;
    /**
     * Show the loading pulse overlay. Default: follows chart loading phase.
     * Set `false` to disable even during loading.
     */
    loading?: boolean;
    /** Override pulse animation mode (loop / exit / enter). */
    loadingPulseMode?: LineLoadingPulseMode;
    /**
     * Loading animation while the chart is in loading status: the default
     * traveling `"pulse"`, or a diagonal `"sweep"` shimmer across the skeleton
     * area. Default: `"pulse"`.
     */
    loadingStyle?: LoadingStyle;
}
function useAreaLoadingPulseState(chartPhase: ChartPhase, loading: boolean | undefined, loadingPulseMode: LineLoadingPulseMode | undefined, notifyLoadingPulseComplete?: () => void) {
    const phasePulseMode = resolveLineLoadingPulseMode(chartPhase);
    const pulseMode = loading === false
        ? null
        : (loadingPulseMode ?? (loading === true ? "loop" : phasePulseMode));
    const showLoadingPulse = pulseMode != null;
    const showSeriesContent = chartPhase === "revealing" ||
        chartPhase === "ready" ||
        chartPhase === "exitingReady";
    const [pulseEpoch, setPulseEpoch] = useState(0);
    const timerRef = useRef<number | null>(null);
    useEffect(() => () => {
        if (timerRef.current !== null)
            window.clearTimeout(timerRef.current);
    }, [pulseMode]);
    const handleLoadingPulseComplete = useCallback(() => {
        if (pulseMode === "loop") {
            if (timerRef.current !== null)
                window.clearTimeout(timerRef.current);
            timerRef.current = window.setTimeout(() => {
                timerRef.current = null;
                setPulseEpoch((epoch) => epoch + 1);
            }, LINE_LOADING_LOOP_PAUSE_MS);
            return;
        }
        notifyLoadingPulseComplete?.();
    }, [notifyLoadingPulseComplete, pulseMode]);
    return {
        handleLoadingPulseComplete,
        pulseMode,
        pulseEpoch,
        showLoadingPulse,
        showSeriesContent,
    };
}
export function Area({ dataKey, stackId, yAxisId, fill = chartCssVars.linePrimary, fillOpacity = 0.4, stroke, strokeWidth = 2, curve = curveMonotoneX, animate = true, showLine = true, showHighlight = true, gradientToOpacity = 0, gradientSpan = 1, fadeEdges = false, showMarkers = false, markers, dashFromIndex, dashArray = "6,4", loading, loadingStroke = chartCssVars.foreground, loadingStrokeOpacity = 0.5, loadingPulseMode, loadingStyle = "pulse", }: AreaProps) {
    const reducedMotion = useReducedMotion();
    // Stable slice only: hover state lives inside `<SeriesHoverDim>` and
    // `<SeriesHighlightLayer>` so this component (and its expensive
    // <SeriesDashTailOverlay> child) does not re-render on cursor motion.
    // The reveal-clip is now a single shared clipPath at the chart-shell
    // level (`time-series-chart-shell.tsx`); we no longer render a per-area
    // `<ChartRevealClip>` or read `revealEpoch` here.
    const { data, renderData, xScale, innerHeight, innerWidth, xAccessor, lines, chartPhase, notifyLoadingPulseComplete, } = useChartStable();
    const yScale = useYScale(yAxisId);
    const { handleLoadingPulseComplete, pulseMode, pulseEpoch, showLoadingPulse, showSeriesContent, } = useAreaLoadingPulseState(chartPhase, loading, loadingPulseMode, notifyLoadingPulseComplete);
    const seriesIndex = useMemo(() => {
        const index = lines.findIndex((line) => line.dataKey === dataKey);
        return index >= 0 ? index : 0;
    }, [lines, dataKey]);
    const pathRef = useRef<SVGPathElement>(null);
    const hasDashTail = resolveDashTailBounds(dashFromIndex, data.length);
    const { pathLength, pathD } = usePathStrokeMetrics(pathRef, [
        renderData,
        xScale,
        yScale,
        xAccessor,
        dataKey,
        curve,
        dashFromIndex,
        showLine,
        showSeriesContent,
        showLoadingPulse,
    ], showLine && (hasDashTail || showLoadingPulse));
    // Unique IDs for this area
    const uniqueId = useId().replace(/[^a-zA-Z0-9_-]/g, "");
    const idKey = dataKey.replace(/[^a-zA-Z0-9_-]/g, "_");
    const gradientId = `area-gradient-${idKey}-${uniqueId}`;
    const strokeGradientId = `area-stroke-gradient-${idKey}-${uniqueId}`;
    const edgeMaskId = `area-edge-mask-${idKey}-${uniqueId}`;
    const edgeGradientId = `${edgeMaskId}-gradient`;
    const isPatternFill = fill.startsWith("url(");
    const showAreaFill = isPatternFill || fillOpacity > 0;
    const areaFill = isPatternFill ? fill : `url(#${gradientId})`;
    // Resolved stroke color (defaults to fill; pattern URLs need a real color)
    const resolvedStroke = stroke || (isPatternFill ? chartCssVars.linePrimary : fill);
    const rangeFor = useCallback((d: Record<string, unknown>) => {
        const series = lines[seriesIndex];
        return series && stackId !== undefined ? areaStackRange(d, series, lines) :
            isFiniteValue(d[dataKey]) ? [0, d[dataKey]] as [
                number,
                number
            ] : null;
    }, [dataKey, lines, seriesIndex, stackId]);
    const isDefined = useCallback((d: Record<string, unknown>) => rangeFor(d) !== null, [rangeFor]);
    const getY = useCallback((d: Record<string, unknown>) => {
        const range = rangeFor(d);
        return range ? (yScale(range[1]) ?? 0) : 0;
    }, [rangeFor, yScale]);
    // The stroke gradient is only emitted when at least one edge fades, so fall
    // back to the resolved solid color otherwise — avoids an invalid url(#...).
    const fadeSides = resolveFadeSides(fadeEdges);
    const useViewportEdgeFade = fadeSides.any && !isPatternFill;
    let strokePaint = resolvedStroke;
    if (!useViewportEdgeFade && fadeSides.any) {
        strokePaint = `url(#${strokeGradientId})`;
    }
    const highlightEnabled = showHighlight && showLine && !showLoadingPulse && showSeriesContent;
    const showSeriesStroke = showSeriesContent && showLine;
    let visibleStroke = "transparent";
    if (showSeriesStroke && !hasDashTail) {
        visibleStroke = strokePaint;
    }
    const shouldMeasurePath = showLine && (showSeriesContent || showLoadingPulse);
    const seriesLayers = (<>
      {showSeriesContent && showAreaFill ? (stackId !== undefined ? <AreaShape curve={curve} data={renderData} defined={isDefined} fill={areaFill} x={(d) => xScale(xAccessor(d)) ?? 0} y0={(d) => yScale(rangeFor(d)?.[0] ?? 0) ?? 0} y1={getY}/> :
            <AreaClosed curve={curve} data={renderData} defined={isDefined} fill={areaFill} x={(d) => xScale(xAccessor(d)) ?? 0} y={getY} yScale={yScale}/>) : null}

      {shouldMeasurePath ? (<>
          <LinePath curve={curve} data={renderData} defined={isDefined} innerRef={pathRef} stroke={visibleStroke} strokeLinecap="round" strokeWidth={strokeWidth} x={(d) => xScale(xAccessor(d)) ?? 0} y={getY}/>
          {showSeriesStroke ? (<SeriesDashTailOverlay dashArray={dashArray} dashFromIndex={dashFromIndex} data={data} innerHeight={innerHeight} innerWidth={innerWidth} pathD={pathD} pathLength={pathLength} stroke={strokePaint} strokeWidth={strokeWidth} xAccessor={xAccessor} xScale={xScale}/>) : null}
        </>) : null}
    </>);
    // Sweep style owns all loading modes (loop + the exit/enter transitions),
    // drawing its own silhouette; the pulse covers the default style.
    const sweepLoading = !reducedMotion && showLoadingPulse && innerWidth > 0 && loadingStyle === "sweep";
    const pulseLoading = !reducedMotion && showLoadingPulse && innerWidth > 0 && !sweepLoading;
    return (<>
      <AreaGradientDefs edgeGradientId={edgeGradientId} edgeMaskId={edgeMaskId} fadeEdges={fadeEdges} fill={fill} fillOpacity={fillOpacity} gradientId={gradientId} gradientSpan={gradientSpan} gradientToOpacity={gradientToOpacity} innerHeight={innerHeight} innerWidth={innerWidth} isPatternFill={isPatternFill} resolvedStroke={resolvedStroke} strokeGradientId={strokeGradientId}/>

      <SeriesHoverDim dimOpacity={0.6} enabled={showHighlight} seriesIndex={seriesIndex}>
        {useViewportEdgeFade ? (<g mask={`url(#${edgeMaskId})`}>{seriesLayers}</g>) : (seriesLayers)}
      </SeriesHoverDim>
